scripts.modular_exp:
def solve(inputs: dict) -> float:
    base = inputs['BASE']
    exp = inputs['EXP']
    mod = inputs['MOD']

    result = pow(base, exp, mod)
    return float(result)

scripts.lcg:
def solve(inputs: dict) -> float:
    seed = inputs['SEED']
    a = inputs['A']
    b = inputs['B']
    m = inputs['M']
    k = inputs['K']

    x = seed
    for _ in range(k):
        x = (a * x + b) % m

    return float(x)

scripts.multiply_three:
def solve(inputs: dict) -> float:
    a = inputs['A']
    b = inputs['B']
    c = inputs['C']

    result = a * b * c
    return float(result)
